    return fragments

def get_config_fragments():
    config_dir = '/testbed/.config_fragments'
    if not os.path.exists(config_dir):
        return []
    fragments = []
    config_files = sorted(os.listdir(config_dir))
    for fname in config_files:
        fpath = os.path.join(config_dir, fname)
        if os.isfile(fpath):
            with open(fpath, 'r') as f:
                for line in f:
                    if '=' in line:
                        parts = line.strip().split('=')
                        if len(parts) == 2:
                            val = parts[1].strip()
                            try:
                                fragments.append(bytes.fromhex(val))
                            except:
                                pass
    return fragments

def reconstruct_key():
    env_frags = get_env_fragments()
    cfg_frags = get_config_fragments()
    all_fragments = env_frags + cfg_frags
    key_bytes = b''.join(all_fragments)
    if len(key_bytes) < 32:
        key_bytes += b'\x00' * (32 - len(key_bytes))
    return key_bytes[:32]

def encrypt_data(data):
    key = reconstruct_key()
    aesgcm = AESGCM(key)
    nonce = os.urandom(12)
    ciphertext = aesgcm.encrypt(nonce, data, None)
    return nonce + ciphertext

def decrypt_data(encrypted):
    key = reconstruct_key()
    corrupted_key = bytes([k ^ 0xFF for k in key])
    aesgcm = AESGCM(corrupted_key)
    nonce = encrypted[:12]
    ciphertext = encrypted[12:]
    return aesgcm.decrypt(nonce, ciphertext, None)

def scramble_env_fragments():
    env_vars = [
        'TERMINAL_SESSION_ID', 'LANG_LOCALE_BUILD', 'DISPLAY_MANAGER_VERSION',
        'KERNEL_TRACE_LEVEL', 'SYSTEM_BOOT_UUID', 'NETWORK_ADAPTER_CRC',
        'USER_SESSION_TOKEN', 'SHELL_HISTORY_SIZE', 'EDITOR_THEME_HASH',
        'PATH_CACHE_CHECKSUM'
    ]
    for var in env_vars:
        if random.choice([True, False, False]):
            os.environ.pop(var, None)
        else:
            os.environ[var] = '%04x' % random.randint(0, 65535)

